class V{int M=-1>>>8,N=130321;String s(boolean P,String[]L){long A=0;if(P)for(var s:L){int p=(int)(new Long(s)&M);for(int i=2000;i-->0;)p=f(p);A+=p;}else{int[]v=new int[N],w=new int[N];for(int B=0;B<L.length;){int H=0,p=(int)(new Long(L[B++])&M),q=p%10;for(int j=0;j++<2000;){int F=f(p),Q=F%10;H=(H*19+Q-q+9)%N;if(j>3&w[H]<B){A=Math.max(A,v[H]+=Q);w[H]=B;}p=F;q=Q;}}}return A+"";}int f(int s){s^=s<<6&M;s^=s>>5;return s^s<<11&M;}}
